<script lang="ts">
 import {onMount} from 'svelte';
 type Drawer='roadmap'|'status'|null; type Feedback={state:'IDLE'|'RUNNING'|'SUCCESS'|'BLOCKED'|'ERROR';title:string;message:string;code?:string;next?:string}; let drawer:Drawer=null,leftWidth=320,rightWidth=320,roadmap='',selectedId='AICC-CODEX-ONLY-MIGRATION-001',wp:any=null,repo:any=null,auth:any={status:'UNAUTHORIZED'},runtime:any=null,info:any=null,error:any={};let busy=false;let feedback:Feedback={state:'IDLE',title:'等待 Owner 操作',message:'请选择一个 Owner Action。'};
 $: lines=roadmap.split('\n');$: milestone=lines.find(x=>x.startsWith('`M'))?.replaceAll('`','')??'M2 — Authority And Workspace Control';$: wps=lines.filter(x=>x.startsWith('`AICC-')).map(x=>x.replaceAll('`','').replace(',','').trim()).filter((x,i,a)=>a.indexOf(x)===i);
 async function get(url:string){const r=await fetch(url);const d=await r.json();if(!r.ok){const e=typeof d.error==='object'?d.error:{code:d.error,message:d.error};throw Error(`${e.code??'READ_ERROR'}: ${e.message??'读取失败'}`)}return d}
 function setFeedback(f:Feedback){feedback=f} function actionError(e:unknown,title:string,next=''){const code=e instanceof Error?e.message:'ACTION_ERROR';setFeedback({state:'ERROR',title,message:code,code,next})}
 async function load(){setFeedback({state:'RUNNING',title:'正在刷新状态…',message:'正在读取路线图、工作包、仓库和运行时证据。'});await Promise.allSettled([get('/api/roadmap').then(d=>roadmap=d.content),get('/api/repository').then(d=>repo=d),get(`/api/work-packages/${encodeURIComponent(selectedId)}`).then(d=>wp=d),get(`/api/authorization?workPackageId=${selectedId}`).then(d=>auth=d),get('/api/codex/runtime').then(d=>(runtime=d.runtime,info=d.info))]);setFeedback({state:'SUCCESS',title:'状态已刷新',message:'路线图、工作包和本地证据已重新读取。'});}
 async function select(id:string){selectedId=id;try{wp=await get(`/api/work-packages/${encodeURIComponent(id)}`);auth=await get(`/api/authorization?workPackageId=${id}`)}catch(e){error.wp=e instanceof Error?e.message:'WP_ERROR'}}
 async function post(url:string,body:unknown){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok){const e=typeof d.error==='object'?d.error:{code:d.error,message:d.error};throw Error(`${e.code??'ACTION_ERROR'}: ${e.message??'操作失败'}`)}return d}
 async function action(kind:string){busy=true;const labels:any={auth:['正在验证 Owner 授权…','正在检查仓库状态、授权和 Writer Lock。'],start:['正在启动 Codex…','正在启动受管 Codex 进程。'],stop:['正在停止 Codex…','正在请求受管进程停止。'],sync:['正在同步本地 main…','正在执行只读验证后的安全 fast-forward。'],retry:['正在重试…','当前版本暂不支持重试。']};const l=labels[kind]??['正在执行操作…','正在处理 Owner 请求。'];setFeedback({state:'RUNNING',title:l[0],message:l[1]});try{if(kind==='auth'){const result=await post('/api/authorization',{workPackageId:selectedId,confirmed:true});auth=result;setFeedback(result.superseded?{state:'SUCCESS',title:'Owner 授权已更新',message:'旧授权已失效，新的授权已绑定当前 HEAD。',code:'AUTHORIZATION_REAUTHORIZED'}:{state:'SUCCESS',title:'Owner 授权已创建',message:`工作包 ${selectedId} 已获得明确授权。`})}if(kind==='start'){runtime=await post('/api/codex/start',{workPackageId:selectedId});poll();setFeedback({state:'SUCCESS',title:'Codex 已启动',message:`PID: ${runtime.pid??'—'} · Thread: ${runtime.threadId??'启动中'}`})}if(kind==='stop'){await post('/api/codex/stop',{});await runtimeLoad();setFeedback({state:'SUCCESS',title:'Codex 已停止',message:'受管 Codex 进程已进入停止流程。'})}if(kind==='sync'){await post('/api/repository/sync-main',{});await load();setFeedback({state:'SUCCESS',title:'本地 main 已同步',message:'本地 main 已完成安全同步。'})}if(kind==='retry')setFeedback({state:'BLOCKED',title:'当前版本暂不支持此操作',message:'重试 / resume 尚未实现。',code:'NOT_IMPLEMENTED'})}catch(e){actionError(e,kind==='start'?'无法启动 Codex':'Owner 操作未完成',kind==='auth'?'点击「确认授权」重新尝试':'请先刷新状态并检查证据。')}busy=false}
 async function runtimeLoad(){try{const d=await get('/api/codex/runtime');runtime=d.runtime;info=d.info}catch(e){error.runtime=e instanceof Error?e.message:'RUNTIME_ERROR'}}
 let timer:number|undefined;function poll(){if(timer)clearInterval(timer);timer=window.setInterval(async()=>{await runtimeLoad();if(!runtime||!['STARTING','RUNNING','STOPPING'].includes(runtime.phase)){clearInterval(timer);timer=undefined}},1000)}
 function resize(side:'left'|'right',e:PointerEvent){const x=e.clientX,s=side==='left'?leftWidth:rightWidth;const m=(n:PointerEvent)=>{const v=Math.max(side==='left'?240:260,Math.min(420,s+(side==='left'?n.clientX-x:x-n.clientX)));if(side==='left')leftWidth=v;else rightWidth=v};const u=()=>{removeEventListener('pointermove',m);removeEventListener('pointerup',u);localStorage.setItem(`aicc-v2-${side}-width`,String(side==='left'?leftWidth:rightWidth))};addEventListener('pointermove',m);addEventListener('pointerup',u)}
 onMount(()=>{leftWidth=+localStorage.getItem('aicc-v2-left-width')!||320;rightWidth=+localStorage.getItem('aicc-v2-right-width')!||320;void load()});
</script>
<svelte:head><title>AICC V2 · Control Center</title><meta name="viewport" content="width=device-width, initial-scale=1"/></svelte:head>
<div class="app-shell"><header class="global-header"><div class="brand"><div class="brand-icon">A</div><div><strong>AI Control Center</strong><span>V2 · Local Web First</span></div></div><div class="header-context"><span class="status-dot"></span>本地工作区 <span class="mono">AIcontrolcenter</span></div><div class="header-actions"><button class="mobile-trigger" onclick={()=>drawer=drawer==='roadmap'?null:'roadmap'}>☰</button><span class="branch-badge">{repo?.branch??'rebuild/aicc-v2'}</span><button class="mobile-trigger" onclick={()=>drawer=drawer==='status'?null:'status'}>◌</button></div></header>
<div class="workspace" style={`--left-width:${leftWidth}px;--right-width:${rightWidth}px`}><aside class:drawer-open={drawer==='roadmap'} class="roadmap panel"><div class="panel-header"><div><span class="kicker">01 / ROADMAP</span><h2>项目路线图</h2></div></div><div class="roadmap-source"><span class="live-dot"></span>唯一展示来源<code>01_LIVING_ROADMAP.md</code></div><div class="roadmap-content"><div class="milestone"><span class="milestone-marker">M2</span><div><strong>{milestone}</strong><small>当前里程碑</small></div></div><div class="tree-line"></div>{#each wps.slice(0,7) as id,i}<button class:current={id===selectedId} class="roadmap-item" onclick={()=>select(id)}><span class="item-marker">{id===selectedId?'●':i<3?'✓':'○'}</span><span><strong>{id}</strong><small>{id===selectedId?'当前工作包 · 进行中':i<3?'已完成':'计划中'}</small></span></button>{/each}</div></aside><div class="resize-handle" onpointerdown={(e)=>resize('left',e)} role="separator" aria-label="调整路线图宽度"></div>
<main class="center panel"><div class="center-inner"><section class="hero"><span class="kicker">CONTROL CENTER / MVP-004</span><h1>保持清醒，<em>掌控变更。</em></h1><p>本地优先的 Codex 控制中心。所有执行能力受 Owner 授权与 Writer Lock 保护。</p></section><section class="action-zone"><div class="section-label"><span>Owner Action Zone</span><small>显式 Owner 操作</small></div><div class="actions"><button class="action primary" onclick={load} disabled={busy}>刷新状态</button><button class="action" onclick={()=>action('auth')} disabled={!repo||!wp||auth.status==='AUTHORIZED'}>确认授权 <small>{auth.status==='AUTHORIZED'?'已授权':'READY'}</small></button><button class="action" onclick={()=>action('start')} disabled={!auth.record||!!runtime&&['STARTING','RUNNING','STOPPING'].includes(runtime.phase)}>启动 Codex <small>{info?.available?'READY':'CHECKING'}</small></button><button class="action" onclick={()=>action('stop')} disabled={!runtime||!['STARTING','RUNNING','STOPPING'].includes(runtime.phase)}>停止 <small>ACTIVE ONLY</small></button><button class="action disabled" disabled>重试<small>NOT_IMPLEMENTED</small></button><button class="action" onclick={()=>action('sync')} disabled={!repo||repo.worktree!=='CLEAN'||repo.branch==='main'}>同步本地 main <small>SAFE FF</small></button></div></section><div class="feedback-bar {feedback.state.toLowerCase()}" data-testid="owner-action-feedback" data-feedback-state={feedback.state.toLowerCase()}><div class="feedback-state">{feedback.state}</div><div><strong>{feedback.title}</strong><p>{feedback.message}</p>{#if feedback.code}<code>{feedback.code}</code>{/if}{#if feedback.next}<small>下一步：{feedback.next}</small>{/if}</div></div><section class="overview"><div class="section-label"><span>Work Package detail</span><small>Read-only source</small></div>{#if error.wp}<div class="detail-error"><strong>工作包读取失败</strong><code>{error.wp}</code><p>Roadmap remains available.</p></div>{:else if wp}<article class="detail-card"><div class="detail-top"><span class="tag">{wp.id}</span><span class="truth">READ ONLY</span></div><h3>{wp.title}</h3><p class="source-path">{wp.source}</p><div class="detail-grid"><div><b>Goal / Scope</b><p>{wp.sections['Goal']??'未提供'}</p></div><div><b>Status</b><p>{wp.fields['Status']??'未提供'}</p></div><div><b>Dependencies</b><p>{wp.sections['Dependencies']??'未提供'}</p></div><div><b>Acceptance Criteria</b><p>{wp.sections['Acceptance Criteria']??'未提供'}</p></div></div></article>{/if}</section></div></main><div class="resize-handle" onpointerdown={(e)=>resize('right',e)} role="separator" aria-label="调整状态宽度"></div>
<aside class:drawer-open={drawer==='status'} class="status panel"><div class="panel-header"><div><span class="kicker">03 / EVIDENCE</span><h2>状态与证据</h2></div></div><div class="evidence-intro"><span class="live-dot"></span><strong>真实本地证据</strong></div>{#if repo}<div class="evidence-list">{#each [['Repository',repo.repository],['Current Branch',repo.branch],['Current HEAD',repo.head],['Local Main',repo.localMain],['Remote Main',repo.remoteMain],['Worktree',repo.worktree],['Last Commit',repo.lastCommit]] as row}<div><span>{row[0]}</span><code>{row[1]}</code></div>{/each}</div>{/if}<div class="auth-card"><span class="kicker">OWNER AUTHORIZATION</span><strong>Owner 授权 · {auth.status==='AUTHORIZED'?'已授权':auth.status==='INVALID'?'已失效':'未授权'}</strong>{#if auth.record}<p>Work Package: {auth.record.workPackageId}<br/>Branch: {auth.record.branch}<br/>Authority SHA: {auth.record.authoritySha.slice(0,7)}<br/>授权 HEAD: {auth.record.headShaAtAuthorization.slice(0,7)}<br/>当前 HEAD: {repo?.head?.slice(0,7)??'读取中…'}<br/>Authorized At: {auth.record.authorizedAt}</p>{#if repo?.head!==auth.record.headShaAtAuthorization}<small>授权 HEAD 与当前 HEAD 不一致，需要重新授权。<br/><code>HEAD_CHANGED_SINCE_AUTHORIZATION</code></small>{/if}{:else}<p>尚未创建 Owner 授权记录</p>{/if}</div><div class="auth-card runtime-card"><span class="kicker">CODEX RUNTIME</span>{#if runtime}<strong>{runtime.phase}</strong><p>Run ID: {runtime.runId}<br/>PID: {runtime.pid??'—'}<br/>Thread: {runtime.threadId??'—'}<br/>当前任务：{runtime.currentTask}<br/>最近活动：{runtime.latestEvent}</p>{:else}<strong>尚未启动 Codex</strong><p>Codex CLI · {info?.available?'AVAILABLE':'UNAVAILABLE'}<br/>Version · {info?.version??'读取中…'}</p>{/if}</div><div class="runtime-list"><div><span>Writer Lock</span><b>{runtime&&['STARTING','RUNNING','STOPPING'].includes(runtime.phase)?'HELD / 已持有':'NOT_HELD / 已释放'}</b></div></div></aside></div></div>
